// Read exhaustive vectors generated by exp_030_fixed_pwl_rtl.
module tb_fixed_pwl_candidate_a;
    reg valid_in;
    reg signed [15:0] raw_q3;
    reg [10:0] coefficient0_q10;
    reg [10:0] coefficient1_q10;
    reg [10:0] coefficient2_q10;
    reg [10:0] coefficient3_q10;
    wire stage1_valid;
    wire stage2_valid;
    wire [1:0] stage1_slice;
    wire [1:0] stage2_slice;
    wire signed [16:0] stage1_corrected;
    wire signed [16:0] stage2_corrected;
    reg [1023:0] vector_path;
    integer file_handle;
    integer scanned;
    integer stage;
    integer raw_value;
    integer c0;
    integer c1;
    integer c2;
    integer c3;
    integer expected_valid;
    integer expected_slice;
    integer expected_corrected;
    integer checked;

    fixed_pwl_candidate_a #(.SLICE_WIDTH_Q3(1024)) stage1 (
        .valid_in(valid_in), .raw_q3(raw_q3),
        .coefficient0_q10(coefficient0_q10),
        .coefficient1_q10(coefficient1_q10),
        .coefficient2_q10(coefficient2_q10),
        .coefficient3_q10(coefficient3_q10),
        .valid_out(stage1_valid), .slice_index(stage1_slice),
        .corrected_q3(stage1_corrected)
    );
    fixed_pwl_candidate_a #(.SLICE_WIDTH_Q3(256)) stage2 (
        .valid_in(valid_in), .raw_q3(raw_q3),
        .coefficient0_q10(coefficient0_q10),
        .coefficient1_q10(coefficient1_q10),
        .coefficient2_q10(coefficient2_q10),
        .coefficient3_q10(coefficient3_q10),
        .valid_out(stage2_valid), .slice_index(stage2_slice),
        .corrected_q3(stage2_corrected)
    );

    initial begin
        if (!$value$plusargs("VECTORS=%s", vector_path))
            $fatal(1, "VECTORS=<path> is required");
        file_handle = $fopen(vector_path, "r");
        if (file_handle == 0)
            $fatal(1, "cannot open vector file");
        checked = 0;
        while (!$feof(file_handle)) begin
            scanned = $fscanf(
                file_handle, "%d %d %d %d %d %d %d %d %d\n",
                stage, raw_value, c0, c1, c2, c3,
                expected_valid, expected_slice, expected_corrected
            );
            if (scanned == 9) begin
                valid_in = 1'b1;
                raw_q3 = raw_value;
                coefficient0_q10 = c0;
                coefficient1_q10 = c1;
                coefficient2_q10 = c2;
                coefficient3_q10 = c3;
                #1;
                if (stage == 1) begin
                    if (stage1_valid !== expected_valid[0] ||
                        stage1_slice !== expected_slice[1:0] ||
                        stage1_corrected !== expected_corrected[16:0])
                        $fatal(1, "stage1 mismatch at vector %0d raw=%0d", checked, raw_value);
                end else if (stage == 2) begin
                    if (stage2_valid !== expected_valid[0] ||
                        stage2_slice !== expected_slice[1:0] ||
                        stage2_corrected !== expected_corrected[16:0])
                        $fatal(1, "stage2 mismatch at vector %0d raw=%0d", checked, raw_value);
                end else
                    $fatal(1, "invalid stage in vector %0d", checked);
                checked = checked + 1;
            end else if (scanned != -1)
                $fatal(1, "malformed vector after %0d checks", checked);
        end
        $fclose(file_handle);
        valid_in = 1'b0;
        raw_q3 = 16'sd0;
        #1;
        if (stage1_valid !== 1'b0 || stage2_valid !== 1'b0 ||
            stage1_corrected !== 17'sd0 || stage2_corrected !== 17'sd0)
            $fatal(1, "invalid input did not clear output");
        $display("fixed_pwl_candidate_a %0d oracle vectors passed", checked);
        $finish;
    end
endmodule
